class Solution { public int countCompleteComponents(int n,int[][] edges){List<Integer>[] graph=new ArrayList[n];for(int i=0;i<n;i++)graph[i]=new ArrayList<>();for(int[] edge:edges){graph[edge[0]].add(edge[1]);graph[edge[1]].add(edge[0]);}boolean[] visited=new boolean[n];int answer=0;for(int start=0;start<n;start++)if(!visited[start]){Queue<Integer> queue=new ArrayDeque<>();queue.add(start);visited[start]=true;int vertices=0,degreeSum=0;while(!queue.isEmpty()){int node=queue.poll();vertices++;degreeSum+=graph[node].size();for(int next:graph[node])if(!visited[next]){visited[next]=true;queue.add(next);}}if(degreeSum==vertices*(vertices-1))answer++;}return answer;} }
